import re,os
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair (\d+) (input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k=m[1].replace(str(m[2]),'1'); h,w=int(m[4]),int(m[5])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))
I,O=G['Demo pair 1 input'],G['Demo pair 1 output']
h,w=len(I),len(I[0])
from collections import deque
# flood background from border
bg=I[0][0]
vis=[[False]*w for _ in range(h)]
dq=deque()
for i in range(h):
    for j in range(w):
        if (i in(0,h-1) or j in(0,w-1)) and I[i][j]==bg and not vis[i][j]:
            vis[i][j]=True; dq.append((i,j))
while dq:
    i,j=dq.popleft()
    for a,b in((i+1,j),(i-1,j),(i,j+1),(i,j-1)):
        if 0<=a<h and 0<=b<w and not vis[a][b] and I[a][b]==bg:
            vis[a][b]=True; dq.append((a,b))
pred=[[O[i][j]!=I[i][j] for j in range(w)] for i in range(h)]
enc=[[not vis[i][j] and I[i][j]==bg for j in range(w)] for i in range(h)]
for i in range(h):
    print(''.join('X' if pred[i][j] else '.' for j in range(w)), '|', ''.join('E' if enc[i][j] else '.' for j in range(w)))

def f(g):
    from collections import deque
    h,w=len(g),len(g[0]); bg=g[0][0]
    vis=[[g[i][j]==bg for j in range(w)] for i in range(h)]
    dq=deque()
    for i in range(h):
        for j in range(w):
            if (i in(0,h-1) or j in(0,w-1)) and vis[i][j]:
                dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for a,b in((i+1,j),(i-1,j),(i,j+1),(i,j-1)):
            if 0<=a<h and 0<=b<w and not vis[a][b] and g[a][b]==bg:
                vis[a][b]=True; dq.append((a,b))
    return [[4 if not vis[i][j] and g[i][j]==bg else g[i][j] for j in range(w)] for i in range(h)]
print(f(I)==O)
out=f(G['Test input'])
import json; print(json.dumps(out))

